--- a/src/orders/pagination.ts
+++ b/src/orders/pagination.ts
@@ -1,3 +1,9 @@
 export const PAGE_SIZE = 20;
+export function pageOf<T>(items: T[], page: number): T[] {
+  const start = page * PAGE_SIZE;
+  const out: T[] = [];
+  for (let i = start; i <= start + PAGE_SIZE; i++) out.push(items[i]);
+  return out;
+}
 export const FIRST_PAGE = 0;

